<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import PageHeader from '../../components/common/PageHeader.vue'
import {mealsApi,monday,shiftDay,mealNames,textures,type MyMeals,type MySlot} from '../../api/meals'
const week=ref(monday()),data=ref<MyMeals|null>(null),day=ref(0),busy=ref(false),error=ref(''),notice=ref('')
const slots=computed(()=>data.value?.slots.filter(s=>s.day===day.value)||[])
async function load(){if(busy.value)return;busy.value=true;error.value='';notice.value='';data.value=null;try{week.value=monday(week.value);data.value=await mealsApi.mine(week.value)}catch(e){error.value=e instanceof Error?e.message:'读取失败'}finally{busy.value=false}}
async function choose(slot:MySlot,id:string){if(busy.value||!data.value?.menu)return;if(!window.confirm(`确定选择这套${mealNames[slot.meal]}？截止时间前仍可修改。`))return;busy.value=true;error.value='';notice.value='';try{await mealsApi.choose(data.value.menu.id,slot,id);data.value=await mealsApi.mine(week.value);notice.value='选餐已确认。'}catch(e){error.value=e instanceof Error?e.message:'选餐失败，请刷新'}finally{busy.value=false}}
onMounted(()=>{const d=new Date();day.value=(d.getDay()+6)%7;void load()})
</script>
<template><div class="page meals meal-personal"><PageHeader title="我的餐食" subtitle="查看本周每天供应的餐食，结合已核对的饮食要求进行选择。"/><div class="card meal-toolbar"><label for="my-meal-week">查看周次<input id="my-meal-week" v-model="week" class="input" type="date" :disabled="busy"></label><button class="btn" :disabled="busy||!week" @click="load">查看这一周</button></div><p v-if="error" class="meal-error" role="alert">{{ error }}</p><p v-if="notice" class="meal-notice" role="status">{{ notice }}</p><p v-if="busy" role="status">正在处理，请稍候…</p>
 <template v-if="data"><div class="meal-personal-note"><b>{{ data.resident_name }}，您好</b><p v-if="!data.reviewed">您的饮食资料尚未完成核对，或档案有变化。可以先查看菜单，请联系工作人员后再确认选餐。</p><p v-else>“符合登记条件”仅表示通过当前人工登记的规则，不是医疗判断。如有新过敏或不适，请先联系工作人员。</p><p v-if="data.in_care===false">档案当前为已离院状态，不能确认在院餐食。</p></div><p v-if="!data.menu" class="card meal-section">这一周尚未发布菜单，请稍后查看。</p><template v-else><div class="meal-days"><button v-for="n in 7" :key="n" class="btn" :class="{primary:day===n-1}" :aria-pressed="day===n-1" @click="day=n-1">周{{ '一二三四五六日'[n-1] }}<small>{{ shiftDay(data.menu.week_start,n-1).slice(5) }}</small></button></div>
 <section v-for="slot in slots" :key="slot.meal" class="card meal-section"><h2><span class="meal-course-icon"><AppIcon name="leaf" :size="22"/></span>{{ mealNames[slot.meal] }}<small>{{ slot.options.length }} 套餐食可选</small></h2><p>选餐截止：{{ slot.date }} {{ slot.cutoff.slice(0,5) }}（北京时间） <b v-if="slot.closed">· 已截止</b></p><p v-if="slot.selection?.needs_review" class="meal-error">已有选餐需要工作人员重新核对，暂不作为有效备餐依据。</p><div class="meal-summary-grid"><article v-for="option in slot.options" :key="option.id" class="meal-choice" :class="{selected:slot.selection?.option_id===option.id}"><span v-if="slot.selection?.option_id===option.id" class="badge blue">已选择</span><span class="meal-eyebrow">{{ mealNames[slot.meal] }} · {{ textures[option.texture] }}</span><h3>{{ option.name }}</h3><p class="meal-foods">{{ option.foods.join(' · ') }}</p><p>食材：{{ option.ingredients.join('、') }}</p><p>过敏原：{{ option.allergens.join('、') || '本方案未标注；有疑问请询问工作人员' }}</p><p>{{ textures[option.texture] }} · {{ option.tags.join('、') || '无特殊饮食标签' }}</p><p v-if="option.notes">{{ option.notes }}</p><ul v-if="option.reasons.length" class="meal-reasons"><li v-for="why in option.reasons" :key="why">{{ why }}</li></ul><p v-else class="meal-match">符合已登记条件</p><p>剩余 {{ option.remaining }} 份</p><button class="btn primary" :disabled="busy||slot.closed||!data.in_care||option.reasons.length>0||(option.remaining===0&&slot.selection?.option_id!==option.id)" @click="choose(slot,option.id)">{{ slot.selection?.option_id===option.id?'重新确认此方案':'选择这套餐食' }}</button></article></div></section></template></template>
</div></template>
<style src="../../styles/meals.css"></style>
